const COURSE_LESSON_HTML = {
  "kurssArticlesLesson": "\n  <h3>Членови</h3>\n\n  <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Германскиот член не секогаш се совпаѓа со родот на зборот во македонскиот јазик. Затоа именките најдобро е да се учат заедно со членот.</div>\n  </div>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Примери за членови</h4>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Tisch — маса</div>\n      <div class=\"kurss-example\">die Tür — врата</div>\n      <div class=\"kurss-example\">das Messer — нож</div>\n      <div class=\"kurss-example\">das Mädchen — девојче</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♂</span>Често DER</h4>\n    <p class=\"artikuli-explain\">DER често се користи за машки лица, денови, месеци, годишни времиња и некои зборови со одредени завршетоци.</p>\n\n    <h5 class=\"artikuli-subtitle\">Правила</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-er → често DER, на пример: der Computer, der Lehrer <span class=\"artikuli-note\">но не секогаш</span></div>\n      <div class=\"kurss-example\">-ling → често DER, на пример: der Schmetterling</div>\n      <div class=\"kurss-example\">-ismus → често DER, на пример: der Tourismus, der Kapitalismus</div>\n      <div class=\"kurss-example\">машки лица → der Mann, der Vater</div>\n      <div class=\"kurss-example\">професии → der Lehrer, der Arzt</div>\n      <div class=\"kurss-example\">марки на автомобили → der BMW, der Mercedes</div>\n      <div class=\"kurss-example\">денови → der Montag, der Dienstag</div>\n      <div class=\"kurss-example\">месеци → der August, der Dezember</div>\n      <div class=\"kurss-example\">годишни времиња → der Sommer, der Winter</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Примери</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Mann — маж</div>\n      <div class=\"kurss-example\">der Vater — татко</div>\n      <div class=\"kurss-example\">der Montag — понеделник</div>\n      <div class=\"kurss-example\">der August — август</div>\n      <div class=\"kurss-example\">der Sommer — лето</div>\n      <div class=\"kurss-example\">der Lehrer — учител</div>\n      <div class=\"kurss-example\">der Computer — компјутер</div>\n      <div class=\"kurss-example\">der Schmetterling — пеперутка</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♀</span>Често DIE</h4>\n    <p class=\"artikuli-explain\">DIE често се користи за женски лица, множина и зборови со завршетоци -ung, -heit, -keit, -schaft, -ion, -tät, -ei.</p>\n\n    <h5 class=\"artikuli-subtitle\">Правила</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-ung → die Wohnung, die Rechnung</div>\n      <div class=\"kurss-example\">-heit → die Freiheit, die Gesundheit</div>\n      <div class=\"kurss-example\">-keit → die Möglichkeit</div>\n      <div class=\"kurss-example\">-schaft → die Mannschaft</div>\n      <div class=\"kurss-example\">-ion → die Nation</div>\n      <div class=\"kurss-example\">-tät → die Universität</div>\n      <div class=\"kurss-example\">-ei → die Polizei, die Bäckerei</div>\n      <div class=\"kurss-example\">женски лица → die Frau, die Mutter</div>\n      <div class=\"kurss-example\">марки на мотоцикли → die Harley-Davidson, die Yamaha</div>\n      <div class=\"kurss-example\">множина → die Autos, die Häuser</div>\n      <div class=\"kurss-example\">множина речиси секогаш → die Autos, die Häuser, die Kinder</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Примери</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Frau — жена</div>\n      <div class=\"kurss-example\">die Mutter — мајка</div>\n      <div class=\"kurss-example\">die Wohnung — стан</div>\n      <div class=\"kurss-example\">die Rechnung — сметка</div>\n      <div class=\"kurss-example\">die Freiheit — слобода</div>\n      <div class=\"kurss-example\">die Möglichkeit — можност</div>\n      <div class=\"kurss-example\">die Mannschaft — екипа</div>\n      <div class=\"kurss-example\">die Nation — нација</div>\n      <div class=\"kurss-example\">die Universität — универзитет</div>\n      <div class=\"kurss-example\">die Polizei — полиција</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>◇</span>Често DAS</h4>\n    <p class=\"artikuli-explain\">DAS често се користи за деминутиви со -chen / -lein, многу зборови со -ment / -um и глаголи употребени како именки.</p>\n\n    <h5 class=\"artikuli-subtitle\">Правила</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-chen → das Mädchen, das Häuschen</div>\n      <div class=\"kurss-example\">-lein → das Fräulein</div>\n      <div class=\"kurss-example\">-ment → das Instrument</div>\n      <div class=\"kurss-example\">-um → das Zentrum, das Museum</div>\n      <div class=\"kurss-example\">метали → das Gold, das Silber, das Eisen</div>\n      <div class=\"kurss-example\">хемиски елементи → das Eisen, das Kupfer</div>\n      <div class=\"kurss-example\">хотели → das Hotel</div>\n      <div class=\"kurss-example\">бои како именки → das Rot, das Blau</div>\n      <div class=\"kurss-example\">глагол како именка → das Essen, das Lernen</div>\n      <div class=\"kurss-example\">глаголи како именки → das Essen, das Lernen, das Lesen</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Примери</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">das Kind — дете</div>\n      <div class=\"kurss-example\">das Mädchen — девојче</div>\n      <div class=\"kurss-example\">das Häuschen — куќичка</div>\n      <div class=\"kurss-example\">das Instrument — инструмент</div>\n      <div class=\"kurss-example\">das Zentrum — центар</div>\n      <div class=\"kurss-example\">das Museum — музеј</div>\n      <div class=\"kurss-example\">das Essen — јадење / храна</div>\n      <div class=\"kurss-example\">das Lernen — учење</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>!</span>Важни исклучоци / треба да се научат со членот</h4>\n    <p class=\"artikuli-explain\">Кај некои зборови членот не може сигурно да се определи според завршетокот или според родот на зборот во македонскиот јазик. Најдобро е тие да се учат заедно со членот.</p>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Tür — врата</div>\n      <div class=\"kurss-example\">das Messer — нож</div>\n      <div class=\"kurss-example\">die Sonne — сонце</div>\n      <div class=\"kurss-example\">der Mond — месечина</div>\n      <div class=\"kurss-example\">das Mädchen — девојче</div>\n      <div class=\"kurss-example\">das Auto — автомобил</div>\n      <div class=\"kurss-example\">der Käse — сирење</div>\n      <div class=\"kurss-example\">die Gabel — вилушка</div>\n    </div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Завршетоците и групите зборови помагаат да се погоди членот, но тие не се 100% сигурно правило. Ако не си сигурен, учи го зборот заедно со членот.</div>\n  </div>\n",
  "kurssPronounsLesson": "\n  <h3>Заменки</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ, Akkusativ и Dativ — форми на заменките.</div>\n  </div>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>N</span>Nominativ — кој/што?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich — јас</div><div class=\"kurss-example\">du — ти</div><div class=\"kurss-example\">er — тој</div><div class=\"kurss-example\">sie — таа</div><div class=\"kurss-example\">es — тоа</div><div class=\"kurss-example\">wir — ние</div><div class=\"kurss-example\">ihr — вие</div><div class=\"kurss-example\">sie — тие</div><div class=\"kurss-example\">Sie — Вие (учтиво)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>A</span>Akkusativ — кого/што?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mich — мене</div><div class=\"kurss-example\">dich — тебе</div><div class=\"kurss-example\">ihn — него (м.)</div><div class=\"kurss-example\">sie — неа (ж.)</div><div class=\"kurss-example\">es — него (ср.)</div><div class=\"kurss-example\">uns — нас</div><div class=\"kurss-example\">euch — вас</div><div class=\"kurss-example\">sie — нив</div><div class=\"kurss-example\">Sie — Вас (учтиво)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>D</span>Dativ — кому?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mir — (на) мене</div><div class=\"kurss-example\">dir — (на) тебе</div><div class=\"kurss-example\">ihm — (на) него</div><div class=\"kurss-example\">ihr — (на) неа</div><div class=\"kurss-example\">uns — (на) нас</div><div class=\"kurss-example\">euch — (на) вас</div><div class=\"kurss-example\">ihnen — (на) нив</div><div class=\"kurss-example\">Ihnen — (на) Вас (учтиво)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>?</span>Како да ја избереш формата?</h4>\n    <ul class=\"kurss-summary-list\"><li><span class=\"case-blue\">Nominativ</span> — подмет (кој го врши дејството?)</li><li><span class=\"case-red\">Akkusativ</span> — директен објект (кого/што?)</li><li><span class=\"case-green\">Dativ</span> — индиректен објект (кому?)</li></ul>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Примери</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">dich</span>. — Те гледам.</div><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">ihn</span>. — Го гледам.</div><div class=\"kurss-example\">Wir mögen <span class=\"case-red\">euch</span>. — Ве сакаме.</div><div class=\"kurss-example\">Ich helfe <span class=\"case-green\">dir</span>. — Ти помагам.</div><div class=\"kurss-example\">Ich gebe <span class=\"case-green\">ihm</span> ein Buch. — Му давам книга.</div><div class=\"kurss-example\">Wir danken <span class=\"case-green\">euch</span>. — Ви благодариме.</div></div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ е секогаш подмет во реченицата, а Akkusativ и Dativ — објекти. Погледни го глаголот и прашај: <span class=\"case-red\">кого/што?</span> или <span class=\"case-green\">кому?</span></div>\n  </div>\n",
  "kurssPronunciationLesson": "\n            <h3>Самогласки — долги и кратки</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>Во германскиот јазик самогласките можат да бидат долги или кратки. Тоа влијае на изговорот на зборот.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Долга самогласка</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">warm (варм) — топол</div><div class=\"kurss-example\">gut (гӯт) — добар</div><div class=\"kurss-example\">Tat (та̄т) — дело / постапка</div><div class=\"kurss-example\">Flur (флӯр) — ходник</div><div class=\"kurss-example\">Weg (ве̄к) — пат</div><div class=\"kurss-example\">Hut (хӯт) — шапка</div><div class=\"kurss-example\">Hof (хо̄ф) — двор</div><div class=\"kurss-example\">Schlaf (шла̄ф) — сон</div></div>\n              <p class=\"artikuli-explain\">Ако по самогласката следува една согласка, самогласката често се изговара долго.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Кратка самогласка</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Pilz (пилц) — печурка</div><div class=\"kurss-example\">Wort (ворт) — збор</div><div class=\"kurss-example\">Mund (мунт) — уста</div><div class=\"kurss-example\">bald (балт) — наскоро</div><div class=\"kurss-example\">scharf (шарф) — остар</div><div class=\"kurss-example\">Feld (фелт) — поле</div><div class=\"kurss-example\">voll (фол) — полн</div></div>\n              <p class=\"artikuli-explain\">Ако по самогласката следуваат две или повеќе согласки, самогласката често се изговара кратко.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Завршетоци en / el / er</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">singen (зинген) — пее</div><div class=\"kurss-example\">tragen (тра̄ген) — носи</div><div class=\"kurss-example\">Garten (гартен) — градина</div><div class=\"kurss-example\">Vogel (фо̄гел) — птица</div><div class=\"kurss-example\">Segel (зе̄гел) — едро</div><div class=\"kurss-example\">Braten (бра̄тен) — печено месо / печење</div><div class=\"kurss-example\">Bogen (бо̄ген) — лак</div><div class=\"kurss-example\">Spiegel (шпӣгел) — огледало</div><div class=\"kurss-example\">Finger (фингер) — прст</div><div class=\"kurss-example\">Halter (халтер) — држач</div><div class=\"kurss-example\">Arbeiter (арбајтер) — работник</div><div class=\"kurss-example\">Häuser (хојзер) — куќи</div><div class=\"kurss-example\">wieder (вӣдер) — повторно</div><div class=\"kurss-example\">breiter (брајтер) — поширок</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Буквата h како знак за должина</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Rahmen (ра̄мен) — рамка</div><div class=\"kurss-example\">Ohr (о̄р) — уво</div><div class=\"kurss-example\">Kohle (ко̄ле) — јаглен</div><div class=\"kurss-example\">Zahl (ца̄л) — број</div><div class=\"kurss-example\">ihn (ӣн) — него</div><div class=\"kurss-example\">ihm (ӣм) — нему</div><div class=\"kurss-example\">Huhn (хӯн) — кокошка</div><div class=\"kurss-example\">nahm (на̄м) — зеде</div><div class=\"kurss-example\">nehmen (не̄мен) — зема</div><div class=\"kurss-example\">Schuh (шӯ) — чевел</div></div>\n              <p class=\"artikuli-explain\">Во некои зборови h ја продолжува претходната самогласка. Во такви случаи h обично не се изговара.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Завршетоци со e</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Lampe (лампе) — ламба</div><div class=\"kurss-example\">Hase (ха̄зе) — зајак</div><div class=\"kurss-example\">Knabe (кна̄бе) — момче</div><div class=\"kurss-example\">Rabe (ра̄бе) — гавран</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Долгото i = ie</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">die (дӣ) — член „die“</div><div class=\"kurss-example\">diese (дӣзе) — оваа / овие</div><div class=\"kurss-example\">wieder (вӣдер) — повторно</div><div class=\"kurss-example\">Fliege (флӣге) — мува</div><div class=\"kurss-example\">Ziege (цӣге) — коза</div><div class=\"kurss-example\">Stiel (штӣл) — дршка / стебло</div><div class=\"kurss-example\">Dieb (дӣп) — крадец</div><div class=\"kurss-example\">hier (хӣр) — тука</div></div>\n              <p class=\"artikuli-explain\">Долгото i во германскиот јазик често се пишува како ie.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Двојни самогласки</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Saal (за̄л) — сала</div><div class=\"kurss-example\">Saat (за̄т) — сеидба / семе</div><div class=\"kurss-example\">Staat (шта̄т) — држава</div><div class=\"kurss-example\">Beere (бе̄ре) — бобинка</div><div class=\"kurss-example\">See (зе̄) — езеро / море</div><div class=\"kurss-example\">Beet (бе̄т) — леја</div><div class=\"kurss-example\">Boot (бо̄т) — чамец</div><div class=\"kurss-example\">Moor (мо̄р) — мочуриште</div><div class=\"kurss-example\">Moos (мо̄с) — мов</div></div>\n              <p class=\"artikuli-explain\">Двојните самогласки обично се изговараат долго.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ä</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Wand (вант) — ѕид</div><div class=\"kurss-example\">Wände (венде) — ѕидови</div><div class=\"kurss-example\">Vater (фа̄тер) — татко</div><div class=\"kurss-example\">Väter (фе̄тер) — татковци</div><div class=\"kurss-example\">Schrank (шранк) — орман</div><div class=\"kurss-example\">Schränke (шренке) — ормани</div><div class=\"kurss-example\">Bank (банк) — клупа / банка</div><div class=\"kurss-example\">Bänke (бенке) — клупи</div><div class=\"kurss-example\">Tal (та̄л) — долина</div><div class=\"kurss-example\">Täler (те̄лер) — долини</div></div>\n              <p class=\"artikuli-explain\">ä е преглас (умлаут) на a.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ö</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Rose (ро̄зе) — роза</div><div class=\"kurss-example\">Röschen (рӧ̄схен) — розичка</div><div class=\"kurss-example\">Ofen (о̄фен) — печка</div><div class=\"kurss-example\">Öfen (ӧ̄фен) — печки</div><div class=\"kurss-example\">Rock (рок) — сукња</div><div class=\"kurss-example\">Röcke (рӧке) — сукњи</div></div>\n              <p class=\"artikuli-explain\">ö е преглас (умлаут) на o.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ü</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">kurz (курц) — краток</div><div class=\"kurss-example\">kürzer (кӱрцер) — пократок</div><div class=\"kurss-example\">Kunst (кунст) — уметност</div><div class=\"kurss-example\">Künste (кӱнсте) — уметности</div><div class=\"kurss-example\">Mutter (мутер) — мајка</div><div class=\"kurss-example\">Mütter (мӱтер) — мајки</div></div>\n              <p class=\"artikuli-explain\">ü е преглас (умлаут) на u.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Двогласи: äu</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Baum (баум) — дрво</div><div class=\"kurss-example\">Bäume (бојме) — дрвја</div><div class=\"kurss-example\">Haus (хаус) — куќа</div><div class=\"kurss-example\">Häuser (хојзер) — куќи</div><div class=\"kurss-example\">Strauch (штраух) — грм</div><div class=\"kurss-example\">Sträucher (штројхер) — грмушки</div><div class=\"kurss-example\">Maus (маус) — глушец</div><div class=\"kurss-example\">Mäuse (мојзе) — глувци</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Двогласи: eu</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">heute (хојте) — денес</div><div class=\"kurss-example\">Leute (лојте) — луѓе</div><div class=\"kurss-example\">neu (ној) — нов</div><div class=\"kurss-example\">neun (нојн) — девет</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Двогласи: ei</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">mein (мајн) — мој</div><div class=\"kurss-example\">dein (дајн) — твој</div><div class=\"kurss-example\">sein (зајн) — негов / биде (глагол „да се биде“)</div><div class=\"kurss-example\">frei (фрај) — слободен</div><div class=\"kurss-example\">arbeiten (арбајтен) — работи</div></div>\n            </section>\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>✓</span>Забелешки за изговорот од 2. час</h4>\n              <ul class=\"kurss-summary-list\"><li>во зборовите ich, nicht, rechnen, zeichnen „ch“ се изговара меко</li><li>во зборовите arbeiten и zeichnen „ei“ се изговара како „ај“</li><li>„sp“ на почетокот на зборот се изговара како „шп“</li><li>во глаголот tun буквата „u“ се изговара долго</li></ul>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>✓</span>Резиме</h4>\n              <ul class=\"kurss-summary-list\"><li>една согласка по самогласката → често долга самогласка</li><li>две или повеќе согласки → често кратка самогласка</li><li>h може да ја продолжи самогласката</li><li>ie често значи долго i</li><li>двојните самогласки обично се долги</li></ul>\n            </section>",
  "kurssConsonantsLesson": "\n            <h3>Согласки и комбинации на букви</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>Во германскиот јазик некои согласки и комбинации на букви се изговараат поинаку отколку што се пишуваат. Во овој час се најважните примери за почетници.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Согласки</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">das Rad (ра̄т) — тркало</div><div class=\"kurss-example\">die Räder (ре̄дер) — тркала</div><div class=\"kurss-example\">Bad (ба̄т) — бања</div><div class=\"kurss-example\">Bäder (бе̄дер) — бањи</div></div>\n              <p class=\"artikuli-explain\">На крајот на зборот согласките често не се изговараат исто како што се пишуваат.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ch</h4>\n              <p class=\"artikuli-explain\">„ch“ може да се изговара меко или тврдо. Во некои зборови звучи како „х“, во други поблиску до „к“.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">rechnen (рехнен) — пресметува / смета</div><div class=\"kurss-example\">zeichnen (цајхнен) — црта</div><div class=\"kurss-example\">nicht (нихт) — не</div><div class=\"kurss-example\">schlecht (шлехт) — лош</div><div class=\"kurss-example\">mich (мих) — мене / ме</div><div class=\"kurss-example\">dich (дих) — тебе / те</div><div class=\"kurss-example\">Strauch (штраух) — грм</div><div class=\"kurss-example\">noch (нох) — уште</div><div class=\"kurss-example\">Nacht (нахт) — ноќ</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>sch</h4>\n              <p class=\"artikuli-explain\">„sch“ во германскиот јазик се изговара како македонското „ш“.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Schule (шӯле) — училиште</div><div class=\"kurss-example\">Schüler (шӱ̄лер) — ученик</div><div class=\"kurss-example\">Schiff (шиф) — брод</div><div class=\"kurss-example\">Schraube (шраубе) — шраф / завртка</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>sp и st на почетокот на зборот</h4>\n              <p class=\"artikuli-explain\">На почетокот на зборот или слогот „sp“ често се изговара како „шп“, а „st“ како „шт“.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">spielen (шпӣлен) — игра / свири</div><div class=\"kurss-example\">Sprung (шпрунг) — скок</div><div class=\"kurss-example\">stehen (ште̄ен) — стои</div><div class=\"kurss-example\">Stall (штал) — штала</div><div class=\"kurss-example\">Stand (штант) — состојба / штанд</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>qu</h4>\n              <p class=\"artikuli-explain\">„qu“ во германскиот јазик обично се изговара како „кв“.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Qual (ква̄л) — маки</div><div class=\"kurss-example\">Quartier (квартӣр) — сместување / четврт</div><div class=\"kurss-example\">quer (кве̄р) — попреку</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>s и z</h4>\n              <p class=\"artikuli-explain\">На почетокот на зборот „s“ често звучи како „з“. Буквата „z“ во германскиот јазик звучи како македонското „ц“.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">sagen (за̄ген) — кажува / вели</div><div class=\"kurss-example\">singen (зинген) — пее</div><div class=\"kurss-example\">Rose (ро̄зе) — роза</div><div class=\"kurss-example\">Zahl (ца̄л) — број</div><div class=\"kurss-example\">Zeit (цајт) — време</div><div class=\"kurss-example\">Zink (цинк) — цинк</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>v</h4>\n              <p class=\"artikuli-explain\">Во германскиот јазик „v“ често се изговара како „ф“. Во туѓите зборови често звучи како македонското „в“.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Vater (фа̄тер) — татко</div><div class=\"kurss-example\">von (фон) — од</div><div class=\"kurss-example\">viel (фӣл) — многу</div><div class=\"kurss-example\">vier (фӣр) — четири</div><div class=\"kurss-example\">Villa (вила) — вила</div><div class=\"kurss-example\">Klavier (клавӣр) — пијано</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>x и y</h4>\n              <p class=\"artikuli-explain\">„x“ се изговара како „кс“. „y“ во некои зборови се изговара како „ü“.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Felix (фе̄ликс) — Феликс</div><div class=\"kurss-example\">Axt (акст) — секира</div><div class=\"kurss-example\">Mystik (мӱстик) — мистика</div><div class=\"kurss-example\">Mythe (мӱ̄те) — мит</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ß</h4>\n              <p class=\"artikuli-explain\">„ß“ во германскиот јазик се изговара како „с“.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Fuß (фӯс) — стапало</div><div class=\"kurss-example\">Füße (фӱ̄се) — стапала</div><div class=\"kurss-example\">Grüße (грӱ̄се) — поздрави</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>✓</span>Резиме</h4>\n              <ul class=\"kurss-summary-list\"><li>sch → ш</li><li>sp / st на почетокот → шп / шт</li><li>qu → кв</li><li>z → ц</li><li>v често → ф</li><li>x → кс</li><li>ß → с</li></ul>\n            </section>",
  "kurssVerbBasicsLesson": "\n            <h3>Основи на глаголите</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>Глаголи од 1. час и нивните форми (конјугација)</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Глаголи</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">kommen — доаѓа</div><div class=\"kurss-example\">gehen — оди</div><div class=\"kurss-example\">stehen — стои</div><div class=\"kurss-example\">singen — пее</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>kommen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich komme — јас доаѓам</div><div class=\"kurss-example\">du kommst — ти доаѓаш</div><div class=\"kurss-example\">er kommt — тој доаѓа</div><div class=\"kurss-example\">sie kommt — таа доаѓа</div><div class=\"kurss-example\">wir kommen — ние доаѓаме</div><div class=\"kurss-example\">ihr kommt — вие доаѓате</div><div class=\"kurss-example\">sie kommen — тие доаѓаат</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>gehen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich gehe — јас одам</div><div class=\"kurss-example\">du gehst — ти одиш</div><div class=\"kurss-example\">er geht — тој оди</div><div class=\"kurss-example\">sie geht — таа оди</div><div class=\"kurss-example\">wir gehen — ние одиме</div><div class=\"kurss-example\">ihr geht — вие одите</div><div class=\"kurss-example\">sie gehen — тие одат</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>stehen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich stehe — јас стојам</div><div class=\"kurss-example\">du stehst — ти стоиш</div><div class=\"kurss-example\">er steht — тој стои</div><div class=\"kurss-example\">sie steht — таа стои</div><div class=\"kurss-example\">wir stehen — ние стоиме</div><div class=\"kurss-example\">ihr steht — вие стоите</div><div class=\"kurss-example\">sie stehen — тие стојат</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>singen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich singe — јас пеам</div><div class=\"kurss-example\">du singst — ти пееш</div><div class=\"kurss-example\">er singt — тој пее</div><div class=\"kurss-example\">sie singt — таа пее</div><div class=\"kurss-example\">wir singen — ние пееме</div><div class=\"kurss-example\">ihr singt — вие пеете</div><div class=\"kurss-example\">sie singen — тие пеат</div></div>\n            </section>\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Глаголи од 2. час</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">spielen — игра</div><div class=\"kurss-example\">arbeiten — работи</div><div class=\"kurss-example\">fragen — прашува</div><div class=\"kurss-example\">antworten — одговара</div><div class=\"kurss-example\">rechnen — пресметува</div><div class=\"kurss-example\">zeichnen — црта</div><div class=\"kurss-example\">tun — прави</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>spielen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich spiele — јас играм</div><div class=\"kurss-example\">du spielst — ти играш</div><div class=\"kurss-example\">er spielt — тој игра</div><div class=\"kurss-example\">sie spielt — таа игра</div><div class=\"kurss-example\">wir spielen — ние играме</div><div class=\"kurss-example\">ihr spielt — вие играте</div><div class=\"kurss-example\">sie spielen — тие играат</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>arbeiten</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich arbeite — јас работам</div><div class=\"kurss-example\">du arbeitest — ти работиш</div><div class=\"kurss-example\">er arbeitet — тој работи</div><div class=\"kurss-example\">sie arbeitet — таа работи</div><div class=\"kurss-example\">wir arbeiten — ние работиме</div><div class=\"kurss-example\">ihr arbeitet — вие работите</div><div class=\"kurss-example\">sie arbeiten — тие работат</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>fragen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich frage — јас прашувам</div><div class=\"kurss-example\">du fragst — ти прашуваш</div><div class=\"kurss-example\">er fragt — тој прашува</div><div class=\"kurss-example\">sie fragt — таа прашува</div><div class=\"kurss-example\">wir fragen — ние прашуваме</div><div class=\"kurss-example\">ihr fragt — вие прашувате</div><div class=\"kurss-example\">sie fragen — тие прашуваат</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>antworten</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich antworte — јас одговарам</div><div class=\"kurss-example\">du antwortest — ти одговараш</div><div class=\"kurss-example\">er antwortet — тој одговара</div><div class=\"kurss-example\">sie antwortet — таа одговара</div><div class=\"kurss-example\">wir antworten — ние одговараме</div><div class=\"kurss-example\">ihr antwortet — вие одговарате</div><div class=\"kurss-example\">sie antworten — тие одговараат</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>rechnen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich rechne — јас пресметувам</div><div class=\"kurss-example\">du rechnest — ти пресметуваш</div><div class=\"kurss-example\">er rechnet — тој пресметува</div><div class=\"kurss-example\">sie rechnet — таа пресметува</div><div class=\"kurss-example\">wir rechnen — ние пресметуваме</div><div class=\"kurss-example\">ihr rechnet — вие пресметувате</div><div class=\"kurss-example\">sie rechnen — тие пресметуваат</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>zeichnen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich zeichne — јас цртам</div><div class=\"kurss-example\">du zeichnest — ти црташ</div><div class=\"kurss-example\">er zeichnet — тој црта</div><div class=\"kurss-example\">sie zeichnet — таа црта</div><div class=\"kurss-example\">wir zeichnen — ние цртаме</div><div class=\"kurss-example\">ihr zeichnet — вие цртате</div><div class=\"kurss-example\">sie zeichnen — тие цртаат</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>tun</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich tue — јас правам</div><div class=\"kurss-example\">du tust — ти правиш</div><div class=\"kurss-example\">er tut — тој прави</div><div class=\"kurss-example\">sie tut — таа прави</div><div class=\"kurss-example\">wir tun — ние правиме</div><div class=\"kurss-example\">ihr tut — вие правите</div><div class=\"kurss-example\">sie tun — тие прават</div></div>\n            </section>",
  "kurssSentenceStructureLesson": "\n            <h3>Градба на реченицата</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>Во прашална реченица глаголот во германскиот јазик обично стои на прво место.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Примери</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Du kommst. — Ти доаѓаш.</div><div class=\"kurss-example\">Kommst du? — Дали доаѓаш?</div><div class=\"kurss-example\">Er singt. — Тој пее.</div><div class=\"kurss-example\">Singt er? — Дали тој пее?</div><div class=\"kurss-example\">Stehst du? — Дали стоиш?</div><div class=\"kurss-example\">Ja, ich stehe. — Да, стојам.</div><div class=\"kurss-example\">Geht ihr? — Дали одите?</div><div class=\"kurss-example\">Ja, wir gehen. — Да, одиме.</div></div>\n            </section>\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Прашања со „was“</h4>\n              <p class=\"artikuli-explain\">Ако прашањето започнува со прашален збор, глаголот во германскиот јазик обично стои веднаш по прашалниот збор.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Was tust du? — Што правиш?</div><div class=\"kurss-example\">Was tut er? — Што прави тој?</div><div class=\"kurss-example\">Was tut sie? — Што прави таа?</div><div class=\"kurss-example\">Was tun sie? — Што прават тие?</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Негација со „nicht“</h4>\n              <p class=\"artikuli-explain\">Ако негацијата „nicht“ се однесува на глаголот, во германскиот јазик таа обично стои по глаголот.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich spiele nicht. — Не играм.</div><div class=\"kurss-example\">Paul fragt nicht. — Паул не прашува.</div><div class=\"kurss-example\">Er kommt nicht. — Тој не доаѓа.</div><div class=\"kurss-example\">Sie singen nicht. — Тие не пеат.</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Реченици од лекција 2</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Spielst du? — Дали играш?</div><div class=\"kurss-example\">Nein, ich spiele nicht, ich arbeite. — Не, не играм, работам.</div><div class=\"kurss-example\">Paul fragt nicht, er arbeitet. — Паул не прашува, тој работи.</div><div class=\"kurss-example\">Arbeitest du? — Дали работиш?</div><div class=\"kurss-example\">Nein, ich arbeite nicht, ich singe. — Не, не работам, пеам.</div><div class=\"kurss-example\">Was tut Paul? — Што прави Паул?</div><div class=\"kurss-example\">Er spielt. — Тој игра.</div><div class=\"kurss-example\">Was tut Marie? — Што прави Мари?</div><div class=\"kurss-example\">Sie singt. — Таа пее.</div><div class=\"kurss-example\">Paul spielt, aber Marie singt. — Паул игра, но Мари пее.</div><div class=\"kurss-example\">Singt ihr? — Дали пеете?</div><div class=\"kurss-example\">Nein, wir singen nicht, wir arbeiten. — Не, не пееме, работиме.</div><div class=\"kurss-example\">Was tun Paul und Marie? — Што прават Паул и Мари?</div><div class=\"kurss-example\">Sie fragen. — Тие прашуваат.</div><div class=\"kurss-example\">Sie antworten nicht. — Тие не одговараат.</div><div class=\"kurss-example\">Wer arbeitet? — Кој работи?</div><div class=\"kurss-example\">Wir arbeiten. — Ние работиме.</div><div class=\"kurss-example\">Wir rechnen und zeichnen. — Ние сметаме и цртаме.</div><div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen. — Тие доаѓаат, прашуваат, одговараат, работат, играат, пеат и одат.</div></div>\n            </section>",
  "kurssLesson2": "            <h3>Лекција 2</h3>\n            <p class=\"kurss-lesson-intro\">Втора лекција: дијалози, зборови, изговор, граматика и преведување.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Дијалози / реченици</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">Spielst du?<br>Nein, ich spiele nicht, ich arbeite.</div>\n                  <div class=\"kurss-example\">Paul fragt nicht, er arbeitet.</div>\n                  <div class=\"kurss-example\">Arbeitest du?<br>Nein, ich arbeite nicht, ich singe.</div>\n                  <div class=\"kurss-example\">Was tut Paul?<br>Er spielt.</div>\n                  <div class=\"kurss-example\">Was tut Marie?<br>Sie singt.</div>\n                  <div class=\"kurss-example\">Paul spielt, aber Marie singt.</div>\n                  <div class=\"kurss-example\">Singt ihr?<br>Nein, wir singen nicht, wir arbeiten.</div>\n                  <div class=\"kurss-example\">Was tun Paul und Marie?<br>Sie fragen.<br>Sie antworten nicht.</div>\n                  <div class=\"kurss-example\">Wer arbeitet?<br>Wir arbeiten.<br>Wir rechnen und zeichnen.</div>\n                  <div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen.</div>\n                </div>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Зборови</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">spielen — си игра; игра</div>\n                  <div class=\"kurss-example\">nein — не</div>\n                  <div class=\"kurss-example\">nicht — не</div>\n                  <div class=\"kurss-example\">arbeiten — работи</div>\n                  <div class=\"kurss-example\">fragen — прашува</div>\n                  <div class=\"kurss-example\">was tut er? — што прави тој?</div>\n                  <div class=\"kurss-example\">was tun sie? — што прават тие?</div>\n                  <div class=\"kurss-example\">aber — но</div>\n                  <div class=\"kurss-example\">antworten — одговара</div>\n                  <div class=\"kurss-example\">rechnen — смета</div>\n                  <div class=\"kurss-example\">zeichnen — црта</div>\n                  <div class=\"kurss-example\">Marie — Марија</div>\n                </div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Изговор</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Во зборовите ich, nicht, rechnen, zeichnen гласот ch се изговара меко, приближно како мекото х во македонските зборови хемија, химна.</div><div class=\"kurss-example\">Во зборовите arbeiten, zeichnen дифтонгот ei се изговара приближно како македонското ај.</div><div class=\"kurss-example\">Групата согласки sp се изговара како шп: spielen (шпилен).</div><div class=\"kurss-example\">Во глаголот tun, u се изговара долго во сите лица.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Граматика</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>1</span>Наставки со e</h4>\n                  <div class=\"lesson1-grammar-note\">Ако основата на глаголот завршува на t, d, chn, при менувањето пред наставките -st и -t се вметнува e.</div>\n                  <h5 class=\"lesson2-subtitle\">arbeiten</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich arbeite</div><div class=\"kurss-example\">du arbeitest</div><div class=\"kurss-example\">er arbeitet</div><div class=\"kurss-example\">sie arbeitet</div><div class=\"kurss-example\">wir arbeiten</div><div class=\"kurss-example\">ihr arbeitet</div><div class=\"kurss-example\">sie arbeiten</div></div>\n                  <h5 class=\"lesson2-subtitle\">rechnen</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich rechne</div><div class=\"kurss-example\">du rechnest</div><div class=\"kurss-example\">er rechnet</div><div class=\"kurss-example\">sie rechnet</div><div class=\"kurss-example\">wir rechnen</div><div class=\"kurss-example\">ihr rechnet</div><div class=\"kurss-example\">sie rechnen</div></div>\n                  <h5 class=\"lesson2-subtitle\">tun</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich tue</div><div class=\"kurss-example\">du tust</div><div class=\"kurss-example\">er tut</div><div class=\"kurss-example\">sie tut</div><div class=\"kurss-example\">wir tun</div><div class=\"kurss-example\">ihr tut</div><div class=\"kurss-example\">sie tun</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>2</span>Прашален збор</h4>\n                  <div class=\"lesson1-grammar-note\">Во прашалните реченици што почнуваат со прашален збор, на пример: што? кој? кој од нив? зошто? поради што? итн., глаголот стои веднаш по прашалниот збор.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Was tust du? — Што правиш?</div><div class=\"kurss-example\">Was tut er? — Што прави тој?</div><div class=\"kurss-example\">Was tut sie? — Што прави таа?</div><div class=\"kurss-example\">Was tun sie? — Што прават тие?</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>3</span>Негација со nicht</h4>\n                  <div class=\"lesson1-grammar-note\">Ако негацијата nicht се однесува на глаголот, таа стои по глаголот.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Er kommt nicht. — Тој не доаѓа.</div><div class=\"kurss-example\">Sie singen nicht. — Тие не пеат.</div></div>\n                </section>\n              </div>\n            </details>\n                                    <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Преведи</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson2-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Лекција 2 картичка за преведување\">\n                    <span class=\"lesson1-training-progress\">Лекција 2 · Преведи: 1 / 15</span>\n                    <span class=\"lesson1-training-text\">Кој прашува?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Кликни на картичката за да го видиш германскиот превод. По одговорот, следниот клик ја прикажува следната картичка.</p>\n                </div>\n              </div>\n            </details>",
  "kurssLesson6": "\n    <h3>Лекција 6</h3>\n    <p class=\"kurss-lesson-intro\">Броеви, множина, умлаути и форми за множина на именките.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Дијалози / реченици</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier liegt ein Bleistift.</div><div class=\"kurss-example\">Dort liegen einige Messer.</div><div class=\"kurss-example\">Edgar nimmt ein Messer, zwei Messer, drei Messer.</div><div class=\"kurss-example\">Er legt die Messer wieder hin.</div><div class=\"kurss-example\">Alle Messer sind scharf.</div><div class=\"kurss-example\">Dann nimmt er wieder ein Messer.</div><div class=\"kurss-example\">Er macht das Messer auf.</div><div class=\"kurss-example\">Er nimmt den Bleistift.</div><div class=\"kurss-example\">Er spitzt den Bleistift an.</div><div class=\"kurss-example\">Er legt das Messer hin.</div><div class=\"kurss-example\">Er setzt sich und zeichnet.</div><div class=\"kurss-example\">Was zeichnet er? Er zeichnet einen Schlüssel.</div><div class=\"kurss-example\">Gertrud zeichnet ein Fenster und eine Tafel.</div><div class=\"kurss-example\">Anna zeichnet einen Garten.</div><div class=\"kurss-example\">Hier liegen vier Löffel.</div><div class=\"kurss-example\">Dort liegen fünf Nadeln.</div><div class=\"kurss-example\">Gertrud kommt und zählt die Löffel: das ist ein Löffel; das sind zwei, drei, vier Löffel.</div><div class=\"kurss-example\">Anna zählt die Nadeln: das ist eine Nadel; das sind zwei, drei, vier, fünf Nadeln.</div><div class=\"kurss-example\">Wieviel Nadeln sind hier?</div><div class=\"kurss-example\">Hier ist eine Nadel.</div><div class=\"kurss-example\">Dort sind zwei, drei, vier Nadeln.</div><div class=\"kurss-example\">Fünf Schlüssel sind hier.</div><div class=\"kurss-example\">Sechs Löffel sind dort.</div><div class=\"kurss-example\">Was ist das?</div><div class=\"kurss-example\">Das ist ein Hammer. Das sind fünf Hämmer.</div><div class=\"kurss-example\">Das ist ein Deckel. Das sind sechs Deckel.</div><div class=\"kurss-example\">Das ist ein Eimer. Das sind sieben Eimer.</div><div class=\"kurss-example\">Das ist ein Teller. Das sind acht Teller.</div><div class=\"kurss-example\">Das ist ein Wagen. Das sind neun Wagen.</div><div class=\"kurss-example\">Das ist ein Schlitten. Das sind zehn Schlitten.</div><div class=\"kurss-example\">Wie sind die Dinge?</div><div class=\"kurss-example\">Der Hammer ist klein. Die Hämmer sind klein.</div><div class=\"kurss-example\">Der Deckel ist groß. Die Deckel sind groß.</div><div class=\"kurss-example\">Der Eimer ist voll. Die Eimer sind voll.</div><div class=\"kurss-example\">Der Teller ist leer. Die Teller sind leer.</div><div class=\"kurss-example\">Der Wagen ist schwer. Die Wagen sind schwer.</div><div class=\"kurss-example\">Der Schlitten ist leicht. Die Schlitten sind leicht.</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Зборови</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">liegt — се наоѓа, има, лежи</div><div class=\"kurss-example\">der Bleistift (блајштифт) — молив</div><div class=\"kurss-example\">einige (ајниге) — неколку</div><div class=\"kurss-example\">hinlegen — остава</div><div class=\"kurss-example\">legt hin — остава</div><div class=\"kurss-example\">wieder (видер) — пак, повторно</div><div class=\"kurss-example\">aufmachen — отвора</div><div class=\"kurss-example\">er macht auf — тој отвора</div><div class=\"kurss-example\">anspitzen (аншпицен) — зашилува</div><div class=\"kurss-example\">er spitzt an — тој зашилува</div><div class=\"kurss-example\">sich setzen — седнува</div><div class=\"kurss-example\">setzt sich — седнува</div><div class=\"kurss-example\">der Schlüssel (шлисел) — клуч</div><div class=\"kurss-example\">das Fenster (фенстер) — прозорец</div><div class=\"kurss-example\">die Tafel (ди тафел) — табла</div><div class=\"kurss-example\">der Garten — градина</div><div class=\"kurss-example\">der Löffel — лажица</div><div class=\"kurss-example\">zählen (целен) — брои</div><div class=\"kurss-example\">die Nadel — игла</div><div class=\"kurss-example\">was ist das — што е тоа?</div><div class=\"kurss-example\">der Hammer — чекан</div><div class=\"kurss-example\">die Hämmer — чекани</div><div class=\"kurss-example\">der Deckel (дер декел) — капак</div><div class=\"kurss-example\">der Teller — чинија</div><div class=\"kurss-example\">der Wagen — кола</div><div class=\"kurss-example\">der Schlitten — санки, саони</div><div class=\"kurss-example\">das Ding — предмет</div><div class=\"kurss-example\">die Dinge — предмети</div><div class=\"kurss-example\">wie sind die Dinge? — какви се предметите?</div><div class=\"kurss-example\">voll (фол) — полн</div><div class=\"kurss-example\">leer (лер) — празен</div><div class=\"kurss-example\">schwer (швер) — тежок, тешко</div><div class=\"kurss-example\">leicht — лесен</div><div class=\"kurss-example\">der Eimer — кофа</div><div class=\"kurss-example\">wieviel (вифил) — колку</div><div class=\"kurss-example\">wieviel Nadeln — колку игли</div><div class=\"kurss-example\">hier (хир) — овде</div><div class=\"kurss-example\">dort — таму</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Изговор</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ä е умлаут на самогласката a и се изговара како кратко или долго затворено е.</div><div class=\"kurss-example\">Примери: das Mädchen (медхен), die Bänke (ди бенке), der Vater (дер фатер), die Väter (ди фетер).</div><div class=\"kurss-example\">ü е умлаут на самогласката u. При изговорот усните треба силно да се заоблат и со заоблени усни да се обидеш да изговориш и.</div><div class=\"kurss-example\">Примери: fünf, der Schlüssel (шлисел).</div><div class=\"kurss-example\">ö се изговара со заоблени усни, обидувајќи се да се изговори е: der Löffel.</div><div class=\"kurss-example\">Удвоената самогласка означува долга самогласка: leer (лер).</div><div class=\"kurss-example\">Дифтонгот eu се изговара како ој: neun (нојн).</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Граматика</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Граматика и објаснувања</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Нагласениот префикс на сложениот глагол во сегашно време се одделува од глаголот и стои на крајот на реченицата.</div><div class=\"kurss-example\">Примери: hinlegen — er legt hin; aufmachen — er macht auf; anspitzen — er spitzt an.</div><div class=\"kurss-example\">Бројот еден има форми за сите три рода кога се употребува со именка: во машки род ein, во женски род eine, во среден род ein.</div><div class=\"kurss-example\">Примери: ein Schüler — еден ученик; eine Schülerin — една ученичка; ein Kind — едно дете.</div><div class=\"kurss-example\">Броеви: eins, zwei, drei, vier (фир), fünf, sechs (зекс), sieben (зибен), acht, neun (нојн), zehn (цен).</div><div class=\"kurss-example\">Глаголот-врска во германскиот јазик има форма за еднина и за множина: der Schüler ist klein; die Schüler sind klein.</div><div class=\"kurss-example\">Показната заменка во македонскиот јазик се менува по род и број: тој, таа, тоа, тие, но во изрази како „тоа е…“ најчесто останува тоа; во германскиот јазик се користи една форма: das.</div><div class=\"kurss-example\">Примери: тоа е чекан — das ist ein Hammer; тоа е игла — das ist eine Nadel; тоа се чекани — das sind Hämmer; тоа се игли — das sind Nadeln.</div><div class=\"kurss-example\">Der Wagen — кола и der Schlitten — санки во германскиот јазик се употребуваат и во еднина и во множина, иако санки во македонскиот јазик има само множина.</div><div class=\"kurss-example\">Именките од машки и среден род со наставка -er, -el, -en во множина често не добиваат наставка.</div><div class=\"kurss-example\">Примери: der Hammer — die Hämmer; der Garten — die Gärten; das Fenster — die Fenster; das Messer — die Messer.</div><div class=\"kurss-example\">Именките од женски род со наставка -el, -er во множина добиваат -n.</div><div class=\"kurss-example\">Примери: die Nadel — die Nadeln; die Feder — die Federn.</div><div class=\"kurss-example\">Исклучоци: die Mutter (мајка) — die Mütter (мајки); die Tochter (ќерка) — die Töchter (ќерки).</div><div class=\"kurss-example\">Неопределениот член нема множина: das ist ein Wagen — das sind Wagen; das ist eine Nadel — das sind Nadeln.</div><div class=\"kurss-example\">Во изјавната реченица глаголот во прирокот стои на второ место: er legt den Schlüssel hin; dann legt er den Schlüssel hin.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Преведи</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson6-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Лекција 6 картичка за преведување\"><span class=\"lesson1-training-progress\">Лекција 6 · Преведи: 1 / 21</span><span class=\"lesson1-training-text\">Паул зема молив и црта.</span></button><p class=\"lesson1-training-hint\">Кликни на картичката за да го видиш германскиот превод. По одговорот, следниот клик ја прикажува следната картичка.</p></div></div>\n    </details>\n  ",
  "kurssLesson5": "\n    <h3>Лекција 5</h3>\n    <p class=\"kurss-lesson-intro\">Wen?, акузатив, sitzen, fragen и наставката -in.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Дијалози / реченици</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">Wer sitzt und fragt? Der Lehrer sitzt und fragt.</div>\n        <div class=\"kurss-example\">Wer steht und antwortet? Der Schüler steht und antwortet.</div>\n        <div class=\"kurss-example\">Wie antwortet der Schüler? Der Schüler antwortet gut.</div>\n        <div class=\"kurss-example\">Wen lobt der Lehrer? Der Lehrer lobt den Schüler.</div>\n        <div class=\"kurss-example\">Wie ist der Schüler? Der Schüler ist klein.</div>\n        <div class=\"kurss-example\">Ist der Schüler klein oder groß? Er ist klein.</div>\n        <div class=\"kurss-example\">Wen fragt die Lehrerin? Die Lehrerin fragt die Schülerin.</div>\n        <div class=\"kurss-example\">Wie antwortet die Schülerin? Die Schülerin antwortet schlecht.</div>\n        <div class=\"kurss-example\">Was tut die Lehrerin? Sie tadelt die Schülerin.</div>\n        <div class=\"kurss-example\">Die Schülerin ist nicht klein, sie ist groß.</div>\n        <div class=\"kurss-example\">Ein Kind spielt. Das Kind ist artig.</div>\n        <div class=\"kurss-example\">Die Mutter liebt das Kind. Der Vater lobt das Kind.</div>\n      </div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Зборови</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">sitzen (зицен) — седи</div>\n        <div class=\"kurss-example\">fragen (фраген) — прашува</div>\n        <div class=\"kurss-example\">der Lehrer (дер лерер) — учител</div>\n        <div class=\"kurss-example\">gut (гут) — добро</div>\n        <div class=\"kurss-example\">wen (вен) — кого</div>\n        <div class=\"kurss-example\">loben — фали</div>\n        <div class=\"kurss-example\">der Schüler (шилер) — ученик</div>\n        <div class=\"kurss-example\">klein — мал</div>\n        <div class=\"kurss-example\">groß (грос) — голем</div>\n        <div class=\"kurss-example\">die Lehrerin — учителка</div>\n        <div class=\"kurss-example\">die Schülerin — ученичка</div>\n        <div class=\"kurss-example\">schlecht (шлехт) — лошо</div>\n        <div class=\"kurss-example\">tadeln — кара, прекорува</div>\n        <div class=\"kurss-example\">oder (одер) — или</div>\n        <div class=\"kurss-example\">das Kind (кинт) — дете</div>\n        <div class=\"kurss-example\">artig (артих) — послушен</div>\n        <div class=\"kurss-example\">die Mutter — мајка</div>\n        <div class=\"kurss-example\">lieben (либен) — сака</div>\n        <div class=\"kurss-example\">der Vater (фатер) — татко</div>\n      </div></div>\n    </details>\n\n        <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Изговор</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">tz е удвоено z и се изговара како германското z, односно како ц: sitzen (зицен).</div>\n        <div class=\"kurss-example\">Во германските зборови v се изговара како ф: der Vater (фатер).</div>\n        <div class=\"kurss-example\">ß се вика есцет и се изговара како македонското с: groß (грос), weiß (вајс).</div>\n      </div></div>\n    </details>\n\n<details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Граматика</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Номинатив и акузатив</h4><div class=\"lesson1-grammar-note\">Во македонскиот јазик подметот одговара на прашањето кој? или што?, а директниот предмет на прашањето кого? или што?.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Во германскиот јазик прашањето во номинатив е wer? за лица и was? за предмети.</div><div class=\"kurss-example\">Во акузатив прашањето е wen? за лица и was? за предмети.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Промена на членот во акузатив</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Akkusativ: den Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">sitzen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich sitze</div><div class=\"kurss-example\">du sitzt</div><div class=\"kurss-example\">er/sie/es sitzt</div><div class=\"kurss-example\">wir sitzen</div><div class=\"kurss-example\">ihr sitzt</div><div class=\"kurss-example\">sie sitzen</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">fragen + акузатив</h4><div class=\"lesson1-grammar-note\">Глаголот fragen во германскиот јазик бара акузатив.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wen fragt der Lehrer?</div><div class=\"kurss-example\">Der Lehrer fragt den Schüler.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Наставката -in</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Многу именки од женски род се изведуваат со наставката -in.</div><div class=\"kurss-example\">die Lehrerin</div><div class=\"kurss-example\">die Schülerin</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Место на глаголот</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Во изјавната реченица глаголот стои на второ место.</div><div class=\"kurss-example\">Dann geht das Mädchen hinaus und arbeitet.</div><div class=\"kurss-example\">Das Mädchen geht dann hinaus und arbeitet.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Преведи</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson5-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Лекција 5 картичка за преведување\"><span class=\"lesson1-training-progress\">Лекција 5 · Преведи: 1 / 16</span><span class=\"lesson1-training-text\">Кого го сака таткото?</span></button><p class=\"lesson1-training-hint\">Кликни на картичката за да го видиш германскиот превод. По одговорот, следниот клик ја прикажува следната картичка.</p></div></div>\n    </details>\n  ",
  "kurssLesson4": "            <h3>Лекција 4</h3>\n            <p class=\"kurss-lesson-intro\">Акузатив, nehmen, hinlegen, hinausgehen и придавки.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Дијалози / реченици</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Paul kommt und nimmt einen Federhalter.</div><div class=\"kurss-example\">Er zeigt den Federhalter.</div><div class=\"kurss-example\">Er fragt: „Wie ist der Federhalter?“</div><div class=\"kurss-example\">Olga antwortet: „Der Federhalter ist schwarz.“</div><div class=\"kurss-example\">Ist der Federhalter weiß? Nein, der Federhalter ist nicht weiß, er ist schwarz.</div><div class=\"kurss-example\">Marie kommt und nimmt eine Feder.</div><div class=\"kurss-example\">Sie fragt: „Wie ist die Feder?“</div><div class=\"kurss-example\">Olga antwortet: „Die Feder ist spitz.“</div><div class=\"kurss-example\">Ist die Feder stumpf? Nein, die Feder ist nicht stumpf, sie ist spitz.</div><div class=\"kurss-example\">Was legt das Mädchen hin? Es legt die Feder hin.</div><div class=\"kurss-example\">Was nimmst du? Ich nehme ein Messer.</div><div class=\"kurss-example\">Wie ist das Messer? Das Messer ist scharf.</div><div class=\"kurss-example\">Ist das Messer stumpf? Nein, es ist nicht stumpf, es ist scharf.</div><div class=\"kurss-example\">Was legst du hin? Ich lege das Messer, die Feder und den Federhalter hin.</div><div class=\"kurss-example\">Dann gehe ich hinaus und arbeite.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Зборови</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">nehmen (немен) — зема</div><div class=\"kurss-example\">er nimmt (нимт) — тој зема</div><div class=\"kurss-example\">der Federhalter (дер федерхалтер) — перодржач</div><div class=\"kurss-example\">einen Federhalter — перодржач</div><div class=\"kurss-example\">zeigen — покажува</div><div class=\"kurss-example\">schwarz (шварц) — црн</div><div class=\"kurss-example\">weiß (вајс) — бел</div><div class=\"kurss-example\">die Feder (ди федер) — перо</div><div class=\"kurss-example\">eine Feder — перо</div><div class=\"kurss-example\">spitz (шпиц) — зашилен</div><div class=\"kurss-example\">hinlegen — остава</div><div class=\"kurss-example\">legt hin — остава</div><div class=\"kurss-example\">das Mädchen (медхен) — девојче</div><div class=\"kurss-example\">das Messer — нож</div><div class=\"kurss-example\">ein Messer — нож</div><div class=\"kurss-example\">scharf — остар</div><div class=\"kurss-example\">stumpf (штумпф) — тап</div><div class=\"kurss-example\">dann — тогаш, потоа</div><div class=\"kurss-example\">hinaus — надвор</div><div class=\"kurss-example\">hinausgehen — излегува, оди надвор</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Изговор</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Наставките -en, -er, -el се ненагласени, затоа e во нив слабо се слуша: kommen, nehmen, der Federhalter.</div><div class=\"kurss-example\">Во германскиот јазик h може да биде и глас и знак за должина на претходната самогласка.</div><div class=\"kurss-example\">Ако h е знак за должина, не се изговара како глас: nehmen (немен).</div><div class=\"kurss-example\">Ако по самогласката следи само една согласка, самогласката се изговара долго: die (ди) Feder (федер), den (ден).</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Граматика</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Акузатив</h4><div class=\"lesson1-grammar-note\">Во женски и среден род акузативот е ист со номинативот. Се менува само машкиот род.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Nominativ: ein Federhalter, eine Feder, ein Messer.</div><div class=\"kurss-example\">Akkusativ: einen Federhalter, eine Feder, ein Messer.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>nehmen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich nehme</div><div class=\"kurss-example\">du nimmst</div><div class=\"kurss-example\">er/sie nimmt</div><div class=\"kurss-example\">wir nehmen</div><div class=\"kurss-example\">ihr nehmt</div><div class=\"kurss-example\">sie nehmen</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Заменки</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er — машки род</div><div class=\"kurss-example\">sie — женски род</div><div class=\"kurss-example\">es — среден род</div><div class=\"kurss-example\">во множина — sie</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Одделиви глаголи</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hinlegen → ich lege das Messer hin</div><div class=\"kurss-example\">hinausgehen → Marie geht hinaus</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>Придавки</h4><div class=\"lesson1-grammar-note\">Ако придавката во реченицата е дел од прирокот, таа не се менува ни по род ни по број.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist klein</div><div class=\"kurss-example\">die Feder ist klein</div><div class=\"kurss-example\">das Messer ist klein</div><div class=\"kurss-example\">die Messer sind klein</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>6</span>Негација со nicht</h4><div class=\"lesson1-grammar-note\">Ако nicht ја негира придавката, стои пред зборот што се негира.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist nicht weiß</div><div class=\"kurss-example\">das Messer ist nicht scharf</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>7</span>-chen / -lein</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Именките со наставка -chen и -lein се од среден род: das Mädchen.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Преведи</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson4-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Лекција 4 картичка за преведување\"><span class=\"lesson1-training-progress\">Лекција 4 · Преведи: 1 / 16</span><span class=\"lesson1-training-text\">Девојчето зема перодржач.</span></button><p class=\"lesson1-training-hint\">Кликни на картичката за да го видиш германскиот превод. По одговорот, следниот клик ја прикажува следната картичка.</p></div></div></details>",
  "kurssLesson3": "            <h3>Лекција 3</h3>\n            <p class=\"kurss-lesson-intro\">Трета лекција: дијалози, зборови, изговор, граматика и преведување.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Дијалози / реченици</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wer rechnet und zeichnet?<br>Wir rechnen und zeichnen.</div><div class=\"kurss-example\">Wer kommt?<br>Paul und Anna kommen.</div><div class=\"kurss-example\">Was steht hier?<br>Hier steht ein Tisch.</div><div class=\"kurss-example\">Was steht dort?<br>Dort steht eine Bank.</div><div class=\"kurss-example\">Was liegt hier?<br>Hier liegt ein Buch.</div><div class=\"kurss-example\">Was liegt dort?<br>Dort liegt ein Heft.</div><div class=\"kurss-example\">Was hängt hier?<br>Hier hängt ein Bild.</div><div class=\"kurss-example\">Was hängt dort?<br>Dort hängt eine Tafel.</div><div class=\"kurss-example\">Wie ist das Buch?<br>Das Buch ist dick.</div><div class=\"kurss-example\">Wie ist das Heft?<br>Das Heft ist dünn.</div><div class=\"kurss-example\">Wie ist die Bank?<br>Die Bank ist niedrig.</div><div class=\"kurss-example\">Wie ist der Tisch?<br>Der Tisch ist hoch.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Зборови</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wer — кој</div><div class=\"kurss-example\">was — што</div><div class=\"kurss-example\">hier — овде</div><div class=\"kurss-example\">dort — таму</div><div class=\"kurss-example\">der Tisch — маса</div><div class=\"kurss-example\">ein Tisch — маса</div><div class=\"kurss-example\">die Bank — клупа</div><div class=\"kurss-example\">eine Bank — клупа</div><div class=\"kurss-example\">liegen — лежи</div><div class=\"kurss-example\">liegt hier ein Buch? — дали овде има / лежи книга?</div><div class=\"kurss-example\">das Buch — книга</div><div class=\"kurss-example\">ein Buch — книга</div><div class=\"kurss-example\">hängen — виси</div><div class=\"kurss-example\">das Bild — слика</div><div class=\"kurss-example\">ein Bild — слика</div><div class=\"kurss-example\">die Tafel — табла</div><div class=\"kurss-example\">eine Tafel — табла</div><div class=\"kurss-example\">wie — каков, каква</div><div class=\"kurss-example\">ist — е</div><div class=\"kurss-example\">dick — дебел</div><div class=\"kurss-example\">das Heft — тетратка</div><div class=\"kurss-example\">ein Heft — тетратка</div><div class=\"kurss-example\">dünn — тенок</div><div class=\"kurss-example\">niedrig — низок</div><div class=\"kurss-example\">hoch — висок</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Изговор</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Долгиот глас и во германскиот јазик се означува со ie: liegen (лиген), hier (хир), wie (ви).</div><div class=\"kurss-example\">ck е двојно k: dick (дик).</div><div class=\"kurss-example\">Кај придавките и прилозите наставката -ig звучи како меко -ich: niedrig (нидрих).</div><div class=\"kurss-example\">Ако по -ig следи e: -ige, тогаш g се изговара како јасен глас г: niedrige (нидриге) Bänke.</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Граматика</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Подмет</h4><div class=\"lesson1-grammar-note\">Подметот во германскиот јазик одговара на прашањето wer? / was? и стои во номинатив.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Со wer? се прашува за лица.</div><div class=\"kurss-example\">Со was? се прашува за предмети.</div><div class=\"kurss-example\">Wer singt? — Sie singt.</div><div class=\"kurss-example\">Was liegt hier? — Hier liegt ein Buch.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Членови</h4><div class=\"lesson1-grammar-note\">Во германскиот јазик именките имаат 3 рода: машки, женски и среден. Пред именката обично стои зборче што се вика член. Ова зборче не се преведува.</div><h5 class=\"lesson2-subtitle\">Определен член</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">машки род — der</div><div class=\"kurss-example\">женски род — die</div><div class=\"kurss-example\">среден род — das</div><div class=\"kurss-example\">Во множина определениот член за сите три рода е die.</div><div class=\"kurss-example\">der Tisch — die Tische</div><div class=\"kurss-example\">die Bank — die Bänke</div><div class=\"kurss-example\">das Heft — die Hefte</div></div><h5 class=\"lesson2-subtitle\">Неопределен член</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">машки род — ein</div><div class=\"kurss-example\">женски род — eine</div><div class=\"kurss-example\">среден род — ein</div><div class=\"kurss-example\">Неопределениот член нема множина.</div><div class=\"kurss-example\">ein Tisch — Tische</div><div class=\"kurss-example\">ein Heft — Hefte</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Сопствени имиња</h4><div class=\"lesson1-grammar-note\">Пред сопствените имиња не се употребува член.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans spielt, aber Marie singt.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Место на глаголот</h4><div class=\"lesson1-grammar-note\">Во изјавната реченица глаголот стои на второ место.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier hängt eine Karte.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>stehen / liegen / hängen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">На германски за предметите што стојат вертикално се вели дека стојат:<br>der Tisch steht<br>die Bank steht</div><div class=\"kurss-example\">За предметите што се во хоризонтална положба се вели дека лежат:<br>das Buch liegt<br>das Heft liegt</div><div class=\"kurss-example\">Предметите можат и да висат:<br>die Karte hängt<br>die Tafel hängt</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Преведи</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson3-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Лекција 3 картичка за преведување\"><span class=\"lesson1-training-progress\">Лекција 3 · Преведи: 1 / 22</span><span class=\"lesson1-training-text\">Дали сметаш?</span></button><p class=\"lesson1-training-hint\">Кликни на картичката за да го видиш германскиот превод. По одговорот, следниот клик ја прикажува следната картичка.</p></div></div></details>",
  "kurssLesson7": "            <h3>Лекција 7</h3>\n            <p class=\"kurss-lesson-intro\">Седма лекција: заповеден начин, форма на обраќање и множина.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Дијалози / реченици</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans, singe ein Lied! Was tust du? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans und Olga, singt ein Lied! Was tut ihr? Wir singen ein Lied.</div><div class=\"kurss-example\">Fräulein Müller, singen Sie, bitte, ein Lied! Was tun Sie? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans, zähle die Teller! Was tut Hans? Er zählt die Teller.</div><div class=\"kurss-example\">Hans und Olga, zählt die Teller! Was tun Hans und Olga? Sie zählen die Teller.</div><div class=\"kurss-example\">Fräulein Müller, zählen Sie, bitte, die Teller!</div><div class=\"kurss-example\">Hans, öffne das Fenster! Was tut Hans? Er öffnet das Fenster.</div><div class=\"kurss-example\">Hans und Olga, öffnet die Fenster! Was tun Hans und Olga? Sie öffnen die Fenster.</div><div class=\"kurss-example\">Fräulein Müller, öffnen Sie, bitte, alle Fenster!</div><div class=\"kurss-example\">Fräulein Müller öffnet alle Fenster.</div><div class=\"kurss-example\">Das ist der Spiegel. Das sind die Spiegel.</div><div class=\"kurss-example\">Das ist der Lappen. Das sind die Lappen.</div><div class=\"kurss-example\">Das ist der Spaten. Das sind die Spaten.</div><div class=\"kurss-example\">Das ist der Besen. Das sind die Besen.</div><div class=\"kurss-example\">Das ist die Schaufel. Das sind die Schaufeln.</div><div class=\"kurss-example\">Das ist die Schüssel. Das sind die Schüsseln.</div><div class=\"kurss-example\">Das ist das Zimmer. Das sind die Zimmer.</div><div class=\"kurss-example\">Das ist das Ufer. Das sind die Ufer.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Зборови</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">singen — пее</div><div class=\"kurss-example\">singe — пеј</div><div class=\"kurss-example\">singt — пејте</div><div class=\"kurss-example\">singen Sie — пејте</div><div class=\"kurss-example\">das Lied (дас лит) — песна</div><div class=\"kurss-example\">Sie — Вие</div><div class=\"kurss-example\">zählen — брои</div><div class=\"kurss-example\">das Fräulein (фројлајн) — госпоѓица</div><div class=\"kurss-example\">der Müller — воденичар</div><div class=\"kurss-example\">öffnen — отвора</div><div class=\"kurss-example\">das Fenster (фенстер) — прозорец</div><div class=\"kurss-example\">alle — сите</div><div class=\"kurss-example\">der Spiegel (шпигел) — огледало</div><div class=\"kurss-example\">der Lappen — партал, крпа</div><div class=\"kurss-example\">der Spaten — лопата</div><div class=\"kurss-example\">der Besen — метла</div><div class=\"kurss-example\">die Schaufel — лопатка</div><div class=\"kurss-example\">die Schüssel — длабока чинија</div><div class=\"kurss-example\">das Zimmer — соба</div><div class=\"kurss-example\">das Ufer (уфер) — брег</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Изговор</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">sp на почетокот на зборот или слогот се изговара како шп: der Spiegel (дер шпигел).</div><div class=\"kurss-example\">sch се изговара како македонското ш: die Schaufel (ди шауфел), die Schüssel (ди шисел).</div><div class=\"kurss-example\">Дифтонгот äu се изговара како македонското ој: das Fräulein (дас фројлајн).</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Граматика</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Заповеден начин</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Заповедниот начин во 2 лице еднина одговара на 2 лице еднина од глаголот без личната наставка -st, со додавање на наставката -e.</div><div class=\"kurss-example\">Примери: antworte!, arbeite!, öffne!, zeichne!</div><div class=\"kurss-example\">Многу често наставката -e не се употребува ако заповедната форма без неа е едносложна: geh!, steh!, komm!, tu!, sing!, frag!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Заповеден начин во множина</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Заповедната форма во 2 лице множина е еднаква на 2 лице множина од сегашното време, но се употребува без заменка.</div><div class=\"kurss-example\">Примери: antwortet!, arbeitet!, öffnet!, zeichnet!, geht!, steht!, tut!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Форма на обраќање со Sie</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Учтивата форма на обраќање со „Вие“ е еднаква на 3 лице множина. Заменката Sie се пишува со голема буква и стои по глаголот.</div><div class=\"kurss-example\">Примери: antworten Sie!, arbeiten Sie!, öffnen Sie!, zeichnen Sie!, gehen Sie!, stehen Sie!, tun Sie!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>öffnen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Кај глаголот öffnen, поради полесен изговор, во 2 и 3 лице еднина и во 2 лице множина меѓу основата и наставката се вметнува e: du öffnest, er öffnet, ihr öffnet.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Übung / Вежба</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson7-exercise-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Лекција 7 картичка за вежба\"><span class=\"lesson1-training-progress\">Лекција 7 · Übung: 1 / 16</span><span class=\"lesson1-training-text\">fragen — прашува</span></button><p class=\"lesson1-training-hint\">Допри ја картичката за да ги видиш заповедните форми.</p></div></div></details>",
  "kurssLesson1": "            <h3>Лекција 1</h3>\n            <p class=\"kurss-lesson-intro\">Прва лекција: глаголи во сегашно време, зборови, изговор, граматика и преведување.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Глаголи во сегашно време</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info\">Глаголите и нивната промена во сегашно време.</div>\n                <div class=\"lesson1-verb-cards\">\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>kommen — доаѓа</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>komme</strong><span>јас доаѓам</span><span>du</span><strong>kommst</strong><span>ти доаѓаш</span><span>er / sie</span><strong>kommt</strong><span>тој / таа доаѓа</span><span>wir</span><strong>kommen</strong><span>ние доаѓаме</span><span>ihr</span><strong>kommt</strong><span>вие доаѓате</span><span>sie / Sie</span><strong>kommen</strong><span>тие доаѓаат / Вие доаѓате</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>gehen — оди</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>gehe</strong><span>јас одам</span><span>du</span><strong>gehst</strong><span>ти одиш</span><span>er / sie</span><strong>geht</strong><span>тој / таа оди</span><span>wir</span><strong>gehen</strong><span>ние одиме</span><span>ihr</span><strong>geht</strong><span>вие одите</span><span>sie / Sie</span><strong>gehen</strong><span>тие одат / Вие одите</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>stehen — стои</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>stehe</strong><span>јас стојам</span><span>du</span><strong>stehst</strong><span>ти стоиш</span><span>er / sie</span><strong>steht</strong><span>тој / таа стои</span><span>wir</span><strong>stehen</strong><span>ние стоиме</span><span>ihr</span><strong>steht</strong><span>вие стоите</span><span>sie / Sie</span><strong>stehen</strong><span>тие стојат / Вие стоите</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>singen — пее</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>singe</strong><span>јас пеам</span><span>du</span><strong>singst</strong><span>ти пееш</span><span>er / sie</span><strong>singt</strong><span>тој / таа пее</span><span>wir</span><strong>singen</strong><span>ние пееме</span><span>ihr</span><strong>singt</strong><span>вие пеете</span><span>sie / Sie</span><strong>singen</strong><span>тие пеат / Вие пеете</span></div>\n                  </article>\n                </div>\n                <section class=\"lesson1-block\">\n                  <h4>Примери</h4>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Stehst du?<br>Ja, ich stehe.</div><div class=\"kurss-example\">Steht Albert?<br>Ja, er steht.</div><div class=\"kurss-example\">Steht Marta?<br>Ja, sie steht.</div><div class=\"kurss-example\">Wer kommt und singt?<br>Albert und Marta kommen und singen.</div><div class=\"kurss-example\">Geht ihr?<br>Ja, wir gehen.</div><div class=\"kurss-example\">Wer steht und singt?<br>Albert und Marta stehen und singen.</div></div>\n                </section>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Зборови</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info lesson1-vardini-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>Приближниот изговор на зборовите е даден во загради со македонски букви.<br>Тоа важи и за следните лекции.</span></div>\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wir (вир) — ние</div><div class=\"kurss-example\">Во зборот „wir“ буквата i се изговара долго.</div><div class=\"kurss-example\">kommen (комен) — доаѓа</div><div class=\"kurss-example\">gehen (ге-ен) — оди</div><div class=\"kurss-example\">stehen (ште-ен) — стои</div><div class=\"kurss-example\">singen (зинген) — пее</div><div class=\"kurss-example\">du (ду) kommst — ти доаѓаш</div><div class=\"kurss-example\">er (ер) kommt — тој доаѓа</div><div class=\"kurss-example\">sie (зи) kommt — таа доаѓа</div><div class=\"kurss-example\">wer (вер) — кој?</div><div class=\"kurss-example\">ja (ја) — да</div></div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Изговор</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Правилниот изговор на зборовите, запишан со македонски букви, е даден во лекциите.</div><div class=\"kurss-example\">Wir (вир) — ние. Во зборот wir, i секогаш се изговара долго.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Граматика</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>∞</span>Инфинитив</h4><div class=\"lesson1-grammar-note\">Основна форма на глаголот. Инфинитивот обично завршува на -en.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">kommen</div><div class=\"kurss-example\">gehen</div><div class=\"kurss-example\">stehen</div><div class=\"kurss-example\">singen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♟</span>Наставки за сегашно време</h4><div class=\"lesson1-ending-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><div class=\"lesson1-ending-info-body\"><p><strong>Отстрани <span class=\"lesson1-ending-accent\">-en</span> од основната форма на глаголот и додај ја наставката.</strong></p><p>Пример: kommen → komm + наставка</p><div class=\"lesson1-ending-process\" aria-label=\"Образување на сегашното време со наставки\"><div class=\"lesson1-ending-step\"><strong>kommen</strong><span>основна форма</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>отстрани <span class=\"lesson1-ending-accent\">-en</span></strong><span>останува коренот</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>komm</strong><span>корен</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>додај наставка</strong><span>e / st / t</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-results\"><div>komm + <span class=\"lesson1-ending-accent\">e</span> = <strong>komme</strong></div><div>komm + <span class=\"lesson1-ending-accent\">st</span> = <strong>kommst</strong></div><div>komm + <span class=\"lesson1-ending-accent\">t</span> = <strong>kommt</strong></div></div></div></div></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich → -e</div><div class=\"kurss-example\">du → -st</div><div class=\"kurss-example\">er / sie → -t</div><div class=\"kurss-example\">wir → -en</div><div class=\"kurss-example\">ihr → -t</div><div class=\"kurss-example\">sie → -en</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>●</span>Примери</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich komme</div><div class=\"kurss-example\">du kommst</div><div class=\"kurss-example\">er kommt</div><div class=\"kurss-example\">wir kommen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>?</span>Прашални реченици</h4><div class=\"lesson1-grammar-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>Во германската прашална реченица глаголот обично доаѓа на прво место.</span></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Во македонскиот јазик:<br>Ти доаѓаш.<br>Дали доаѓаш?</div><div class=\"kurss-example\">Во германскиот јазик:<br>Du kommst.<br>Kommst du?</div><div class=\"kurss-example\">du kommst — ти доаѓаш<br>kommst du? — дали доаѓаш?</div><div class=\"kurss-example\">er singt — тој пее<br>singt er? — дали тој пее?</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♣</span>Разлика во лицето</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er kommt — тој доаѓа</div><div class=\"kurss-example\">sie kommt — таа доаѓа</div><div class=\"kurss-example\">sie kommen — тие доаѓаат</div></div></section>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Преведи</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson1-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Лекција 1 картичка за вежбање\">\n                    <span class=\"lesson1-training-progress\">Лекција 1 · Преведи: 1 / 11</span>\n                    <span class=\"lesson1-training-text\">Дали доаѓаш?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Кликни на картичката за да го видиш германскиот превод. По одговорот, следниот клик ја прикажува следната картичка.</p>\n                </div>\n              </div>\n            </details>"
};

